(function(){'use strict';
/* Design Database generator — jahdb-design-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-DESIGN-';
var SRC='public';
var RECORD_KIND='design record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Graphic Design Fundamentals","brief":"Graphic design is visual communication: combining typography, imagery, and layout to convey messages clearly and memorably.","points":["The core elements — line, shape, color, texture, space — are the vocabulary of visual communication.","Principles like contrast, alignment, repetition, and proximity (CARP) organize elements into coherent compositions.","Every design serves a message and an audience; decoration without purpose is noise.","Constraints (brand, budget, medium) are not enemies — they focus creativity."],"examples":["A poster using one bold typeface and strong contrast to announce a concert.","An annual report turning dense financials into readable infographics."],"history":["Print posters (19th century) and the Bauhaus (1920s) professionalized the field.","Desktop publishing (1980s) and the web democratized design tools."],"uses":["Branding and marketing communications.","Publishing, packaging, and signage.","Digital interfaces and social media."],"qa":[["Do I need to draw to be a graphic designer?","No — design is about visual problem-solving; drawing helps but software and systems thinking matter more."],["Print vs digital design?","Same principles, different constraints: resolution, color models, and interactivity differ."],["How do I start learning?","Study typography first — it is the foundation of most graphic design."]]},{"title":"Typography","brief":"Typography is the art of arranging type: choosing and setting letterforms so text is readable, expressive, and beautiful.","points":["Typeface anatomy — serifs, x-height, contrast, apertures — determines a font's voice and legibility.","Hierarchy through size, weight, and spacing guides readers through content.","Pairing: limit to two or three families; contrast (serif/sans) or harmony (superfamilies) both work.","Micro-typography — kerning, tracking, leading — separates amateur from professional setting."],"examples":["A book set in a readable serif with generous leading for long-form comfort.","A website pairing a distinctive display face with a neutral text sans."],"history":["Gutenberg's movable type (1440s) began typographic history; Baskerville, Bodoni, and Garamond defined eras.","Digital fonts (1980s PostScript) and web fonts (2010s) made typography universal."],"uses":["Every interface, document, and sign — type is everywhere.","Brand voice expressed through letterforms.","Accessibility: readable type serves all users."],"qa":[["Serif or sans-serif for body text?","Both work — test at your sizes and media; readability depends on execution."],["How many fonts per project?","Two or three: one for display, one for text, maybe one accent."],["What is kerning?","Adjusting space between specific letter pairs so spacing looks optically even."]]},{"title":"Color Theory","brief":"Color theory explains how colors relate, harmonize, and affect viewers — the science and psychology behind palettes.","points":["The color wheel organizes hues; harmonies (complementary, analogous, triadic) create pleasing combinations.","Value (lightness) does more work than hue — squint to check contrast.","Color psychology is contextual: red energizes in one culture, warns in another.","Accessibility: text needs sufficient contrast ratios (WCAG) regardless of aesthetics."],"examples":["A complementary blue-orange palette making a sports brand pop.","A muted analogous palette calming a healthcare website."],"history":["Goethe, Chevreul, and Itten built color theory from the 19th to early 20th century.","Digital color (RGB/CMYK/HSL) made theory instantly applicable."],"uses":["Brand palettes that signal identity.","Interfaces where color encodes meaning and state.","Wayfinding and safety signage."],"qa":[["What is the 60-30-10 rule?","A guideline: 60% dominant, 30% secondary, 10% accent color."],["How do I pick brand colors?","Start from audience psychology and differentiation, then test in context."],["Why do my colors look different on screen vs print?","RGB (light) vs CMYK (ink) gamuts differ — design in the right mode and proof."]]},{"title":"Logo Design","brief":"Logo design distills a brand into a memorable mark: simple, distinctive, and workable at every size.","points":["Great logos are simple, memorable, timeless, versatile, and appropriate.","Wordmarks, lettermarks, pictorial marks, and abstract marks each suit different brands.","Design in black and white first — if it fails in one color, color won't save it.","Test at favicon size and billboard size; a logo must survive both."],"examples":["A wordmark set in custom lettering for a law firm.","An abstract mark suggesting motion for a logistics brand."],"history":["Trademarks are ancient; modern logo design professionalized in the mid-20th century (Paul Rand, Saul Bass).","Responsive logos (2010s) adapt simplified versions for small screens."],"uses":["Brand identity systems across every touchpoint.","App icons and social avatars.","Signage, packaging, and merchandise."],"qa":[["How much should a logo cost?","From hundreds (templates/contests) to six figures (full identity programs) — you get the research and craft you pay for."],["Should a logo describe the business?","No — it should identify it. Meaning accrues through use, not literal illustration."],["How long does logo design take?","Weeks to months with research, concepts, and refinement — not an afternoon."]]},{"title":"Brand Identity Design","brief":"Brand identity design builds the complete visual system — logo, colors, typography, imagery, voice — that makes a brand recognizable.","points":["Identity systems include logo, palette, typefaces, imagery style, and usage guidelines.","Consistency across touchpoints builds recognition; flexibility keeps it alive.","Brand guidelines document the system so everyone applies it correctly.","Rebrands succeed when driven by strategy, not just aesthetics."],"examples":["A coffee chain whose cup, app, and storefront are instantly recognizable.","A nonprofit rebrand unifying 50 chapters under one system."],"history":["Corporate identity programs (1960s-70s) systematized branding.","Digital brands (2000s+) added motion, sound, and adaptive identities."],"uses":["Launching companies with coherent presence.","Unifying organizations after mergers.","Building trust through professional consistency."],"qa":[["Logo vs brand vs identity?","Logo: the mark. Identity: the visual system. Brand: the perception in people's minds."],["When should we rebrand?","When strategy changes (merger, new audience) — not because the logo feels old."],["How do you measure brand success?","Recognition, preference, and ultimately business results — tracked over years."]]},{"title":"UI Design","brief":"UI design crafts the visual layer of interfaces: screens, components, and states users see and touch.","points":["Visual hierarchy, spacing, and alignment make interfaces scannable and calm.","Components (buttons, inputs, cards) built once and reused keep products consistent.","States matter: every component needs default, hover, active, disabled, loading, and error designs.","Platform conventions (iOS, Android, web) set user expectations — follow them unless you have reason."],"examples":["A settings screen with clear grouping, consistent controls, and obvious primary actions.","A design system button with all six states specified."],"history":["GUIs (1980s) created UI design; the iPhone (2007) made mobile UI central.","Design systems (2010s) industrialized component reuse."],"uses":["Apps and websites people use daily.","Embedded displays and kiosks.","Design systems serving whole product teams."],"qa":[["UI vs UX?","UI is the visual surface; UX is the whole experience including research and flows. UI is part of UX."],["Should UI be beautiful or usable?","Both — but usability first; beauty that confuses is decoration."],["What makes a good button?","Clear label, obvious affordance, consistent style, and visible feedback on press."]]},{"title":"UX Design","brief":"UX design shapes the entire user experience: research, flows, and testing to make products useful and usable.","points":["User research (interviews, observation) reveals real needs before solutions.","Information architecture and user flows organize the journey from goal to completion.","Usability testing with real users finds problems no expert review catches.","Iteration: design, test, refine — UX is never one-and-done."],"examples":["Testing a checkout flow and discovering users abandon at the shipping-options step.","Card-sorting research reorganizing a confusing navigation."],"history":["Human factors research (mid-20th c.) and Don Norman's 'Design of Everyday Things' (1988) founded UX.","Lean UX (2010s) sped cycles with continuous testing."],"uses":["Products people can actually use without frustration.","Services spanning digital and physical touchpoints.","Reducing support costs and abandonment."],"qa":[["How is UX measured?","Task success, time on task, error rates, satisfaction (SUS), and business metrics."],["Do I need a UX degree?","No — portfolios demonstrating research-to-design process matter most."],["UX vs product design?","Overlapping titles; product design often includes more UI and business strategy."]]},{"title":"Web Design","brief":"Web design creates websites: visual design plus the web's unique constraints of responsiveness, performance, and accessibility.","points":["Mobile-first: design for small screens, then enhance for larger ones.","Performance is design: every kilobyte and request affects experience.","Accessibility (semantic HTML, contrast, keyboard) is non-negotiable.","Content strategy precedes visuals — design serves the message."],"examples":["A restaurant site where the menu, hours, and reservation button are instantly findable on a phone.","A portfolio loading in under two seconds with optimized images."],"history":["Table layouts (1990s) gave way to CSS, then responsive design (Ethan Marcotte, 2010).","Component frameworks and design systems now dominate production."],"uses":["Business websites that convert visitors.","Publications and portfolios.","Web applications with complex interactions."],"qa":[["How much does a website cost?","From DIY builders to six-figure custom builds — scope and craft set the price."],["What is responsive design?","Layouts that adapt fluidly to any screen size from one codebase."],["Do I need a designer if I use a template?","Templates handle structure; designers handle strategy, content, and differentiation."]]},{"title":"Responsive Design","brief":"Responsive design makes one website adapt gracefully to phones, tablets, desktops, and everything between.","points":["Fluid grids use relative units so layouts flex with viewport width.","Flexible images and media scale without breaking layouts.","Media queries apply different rules at breakpoints — design content-first, not device-first.","Touch targets, readable type, and simplified navigation matter most on small screens."],"examples":["A three-column desktop layout reflowing to one column on a phone.","A navigation menu collapsing into a hamburger on narrow screens."],"history":["Ethan Marcotte's 2010 article coined 'responsive web design'.","Mobile traffic surpassing desktop (mid-2010s) made it mandatory."],"uses":["Every public website serving mixed devices.","Reducing maintenance versus separate mobile sites.","Future-proofing against new screen sizes."],"qa":[["How many breakpoints?","As many as the content needs — typically 3-5, based on where the design breaks."],["Responsive vs separate mobile site?","Responsive wins for most: one codebase, one URL, consistent content."],["Does responsive hurt performance?","Only if done badly — serve appropriately sized images and test on real devices."]]},{"title":"Interaction Design","brief":"Interaction design defines how users act and systems respond: flows, feedback, animations, and micro-interactions.","points":["Affordances signal what can be done; signifiers (labels, icons) clarify how.","Feedback confirms every action — immediate, visible, and proportionate.","Animation guides attention and explains state changes; gratuitous motion annoys.","Error prevention beats error messages: constrain inputs and confirm destructive actions."],"examples":["A toggle animating smoothly so users perceive the state change.","An undo option after deleting, preventing the need for confirmation dialogs."],"history":["Direct manipulation (1980s) and the web made interaction design central.","Material Design (2014) codified motion and feedback patterns."],"uses":["Apps where feel differentiates (social, creative tools).","Complex workflows made learnable.","Reducing errors in critical systems."],"qa":[["What is a micro-interaction?","A single-purpose interactive moment: a like animation, a toggle, a progress indicator."],["How much animation is too much?","When users notice the animation instead of the task — keep it under ~300ms typically."],["Dark patterns?","Manipulative interactions (tricking users) — unethical and increasingly illegal."]]},{"title":"Information Architecture","brief":"Information architecture organizes content so people can find things: navigation, labeling, search, and structure.","points":["Organization schemes (alphabetical, topical, task-based) match how users think.","Navigation should be predictable: clear labels, consistent placement, visible location.","Search complements browsing — both need good metadata.","Card sorting and tree testing validate structures with real users."],"examples":["An e-commerce site reorganized by shopping task instead of internal departments.","A university site where 'admissions' is findable in two clicks from anywhere."],"history":["Richard Saul Wurman coined 'information architect' (1970s); Rosenfeld & Morville's book (1998) defined web IA.","Faceted navigation and search matured IA for large catalogs."],"uses":["Large websites and intranets.","Apps with deep content (media, docs, commerce).","Anywhere users say 'I know it's here somewhere'."],"qa":[["How deep can navigation go?","Three levels is a guideline; test with users — findability matters more than depth rules."],["What is card sorting?","Users group content cards into categories, revealing their mental model."],["IA vs navigation design?","IA is the underlying organization; navigation is its visible expression."]]},{"title":"User Research","brief":"User research studies real people to ground design in evidence: interviews, observation, surveys, and testing.","points":["Qualitative research (interviews, field studies) reveals why; quantitative (surveys, analytics) reveals how many.","Contextual inquiry observes users in their real environment, not a lab.","Recruit representative users — five well-chosen participants find most usability issues.","Research is continuous, not a phase: small studies often beat big ones."],"examples":["Interviewing nurses at their station to redesign a medication app around interruptions.","A five-user test finding that nobody understands the pricing page."],"history":["Human factors (WWII) and Xerox PARC ethnography pioneered the methods.","Lean research (2010s) made continuous small studies normal."],"uses":["De-risking product decisions with evidence.","Discovering unmet needs competitors miss.","Aligning teams on real user problems."],"qa":[["How many users do I need?","Five for qualitative discovery; more for statistical confidence."],["Isn't research slow?","A week of guerrilla research beats months of building the wrong thing."],["What if users ask for features?","Listen for problems, not solutions — users know their pain, designers know the fix."]]},{"title":"Wireframing","brief":"Wireframes are low-fidelity layout sketches: boxes and labels showing structure without visual design.","points":["Low fidelity keeps discussion on structure, not colors and fonts.","Annotate behavior and content rules so wireframes communicate fully.","Iterate fast: wireframes should be disposable, not precious.","Fidelity should match the question — flows need screens, details need prototypes."],"examples":["A checkout wireframe testing whether users find the guest-checkout option.","Whiteboard wireframes aligning a team in one meeting."],"history":["Paper prototyping (1990s) proved low-fi testing works.","Digital tools made wireframes shareable and testable."],"uses":["Exploring layouts quickly before visual design.","Testing information architecture cheaply.","Communicating structure to developers."],"qa":[["Paper or digital wireframes?","Paper for speed and collaboration; digital for remote teams and testing."],["How detailed should wireframes be?","Detailed enough to test the question at hand — no more."],["Do clients understand wireframes?","With explanation, yes — label clearly that visuals come later."]]},{"title":"Prototyping","brief":"Prototypes are interactive models of designs, from paper click-throughs to coded simulations, used to test before building.","points":["Fidelity ladder: paper → clickable → high-fi → coded; climb only as questions demand.","Prototype the riskiest assumptions first, not the whole product.","Test with users: watching real attempts beats stakeholder opinions.","Throwaway mindset: prototypes answer questions, then die."],"examples":["A clickable prototype revealing users miss the primary button.","A coded prototype testing a novel gesture's feel."],"history":["Prototyping is ancient in industrial design; digital tools (2000s+) made it fast.","Figma (2016) made high-fi prototyping collaborative."],"uses":["Validating concepts before engineering investment.","Testing interactions impossible to judge statically.","Selling ideas to stakeholders with tangibility."],"qa":[["Prototype or MVP?","Prototype to learn; MVP to validate in market — prototype first, it's cheaper."],["How polished should a prototype be?","Polished enough that users react to the design, not the roughness."],["What tools?","Figma for most; code for novel interactions; paper for earliest ideas."]]},{"title":"Design Systems","brief":"Design systems are reusable component libraries plus the standards guiding them — product design at scale.","points":["Components: coded, documented UI building blocks with defined states.","Tokens (color, spacing, type) propagate decisions consistently.","Guidelines cover usage, accessibility, voice, and motion — not just pixels.","Governance: contribution models keep the system alive as products evolve."],"examples":["A button component used identically across web, iOS, and Android.","Onboarding docs letting new designers ship consistently in week one."],"history":["Brad Frost's Atomic Design (2013) gave systems a vocabulary.","Material Design and Lightning proved systems at Google/Salesforce scale."],"uses":["Organizations with multiple products or teams.","Consistency without bottlenecking every decision.","Faster onboarding and development."],"qa":[["Isn't a design system just a component library?","Components are the artifact; the system includes standards, tokens, and governance."],["When is a design system overkill?","For a single small product — start with a UI kit and grow into a system."],["Who maintains it?","A dedicated team with product-team contributors — unfunded systems die."]]},{"title":"Design Tokens","brief":"Design tokens are named variables for design decisions — colors, spacing, type — shared between design and code.","points":["Tokens separate intent ('color-action') from value ('#0066FF'), enabling theming.","A single token source feeds design tools and all code platforms.","Theming (light/dark, brand variants) becomes a token swap, not a rewrite.","Versioning tokens like code keeps design changes reviewable."],"examples":["A dark mode shipped by swapping token values, not rewriting components.","A white-label product rebranded by overriding brand tokens."],"history":["Salesforce's Theo (2010s) pioneered tokens; the W3C Design Tokens spec formalized them.","Multi-brand products made tokens essential."],"uses":["Theming and white-labeling.","Multi-platform consistency (web, iOS, Android).","Design decisions tracked like code."],"qa":[["Tokens vs CSS variables?","Tokens are the platform-agnostic source; CSS variables are one output format."],["What should be a token?","Repeated decisions: colors, spacing, radii, type scale, shadows, motion."],["Do tokens slow designers down?","Initially; they pay back in consistency and theming speed."]]},{"title":"Visual Hierarchy","brief":"Visual hierarchy arranges elements so the most important things are seen first — guiding the eye through deliberate emphasis.","points":["Size, weight, color, and position create levels of importance.","One clear primary action per view; everything else recedes.","Whitespace is hierarchy: isolation emphasizes as much as size.","Test with the squint test — the key message should survive blurring."],"examples":["A landing page where the headline, then subhead, then CTA read in order.","A dashboard where alerts visually outweigh routine metrics."],"history":["Hierarchy principles come from print and the Bauhaus tradition.","Eye-tracking studies (2000s) confirmed F and Z scanning patterns."],"uses":["Landing pages that convert.","Dashboards that surface what matters.","Documents people actually read."],"qa":[["How many hierarchy levels?","Three to four: title, section, body, caption — more creates noise."],["What is the squint test?","Squinting (or blurring) to check whether emphasis still reads."],["Does hierarchy manipulate users?","It guides attention — ethical when serving user goals, dark when tricking."]]},{"title":"Layout and Composition","brief":"Layout arranges elements on the page or screen; composition makes the arrangement feel intentional and balanced.","points":["Alignment creates order — pick an edge and stick to it.","Proximity groups related items; distance separates.","Balance (symmetrical or asymmetrical) distributes visual weight.","The rule of thirds and golden ratio are guides, not laws."],"examples":["A magazine spread balancing a large image against columns of text.","A dashboard aligning every card to a common grid."],"history":["Composition theory comes from fine art; Swiss designers systematized it for print.","CSS Grid and Flexbox finally gave the web real layout power."],"uses":["Every designed surface, print or screen.","Presentations that don't induce sleep.","Editorial and marketing materials."],"qa":[["What is the biggest layout mistake?","Centering everything and aligning nothing — pick edges deliberately."],["How do I learn composition?","Recreate layouts you admire; analysis builds intuition."],["Symmetric or asymmetric?","Symmetric feels stable and formal; asymmetric feels dynamic and modern."]]},{"title":"Grid Systems","brief":"Grids are invisible scaffolding — columns, rows, and gutters that bring order to layouts.","points":["Column grids (12-column is classic) let elements span consistently.","Baseline grids align text across columns for print-like rhythm.","Break the grid deliberately for emphasis — but know the grid first.","CSS Grid implements true two-dimensional layouts on the web."],"examples":["A 12-column web grid aligning hero, features, and footer.","A book's baseline grid keeping facing pages in register."],"history":["Swiss designers (1950s-60s) made the grid a design religion.","Bootstrap (2011) brought grids to every web developer."],"uses":["Multi-page documents and publications.","Complex web layouts with many components.","Any team needing layout consistency."],"qa":[["Do I always need a grid?","For structured content, yes; expressive one-offs can break free."],["12 columns — why?","Divisible by 2, 3, 4, and 6 — maximum layout flexibility."],["Grid vs flexbox?","Grid for two-dimensional layout; flexbox for one-dimensional distribution."]]},{"title":"Accessibility in Design","brief":"Accessible design works for everyone, including people with disabilities — and usually works better for everyone else too.","points":["Perceivable: sufficient contrast, text alternatives for images, captions for audio.","Operable: keyboard access, enough time, no seizure-triggering flashes.","Understandable: clear language, predictable behavior, error help.","Robust: semantic markup that assistive tech can parse."],"examples":["A form every field of which is labeled and fully keyboard-operable.","A video with accurate captions benefiting deaf and gym-watchers alike."],"history":["Section 508 (1998) and WCAG (1999+) set the standards.","Lawsuits and awareness (2010s+) made accessibility mainstream."],"uses":["Legal compliance and risk reduction.","Reaching the 15%+ of users with disabilities.","Better usability for everyone (curb-cut effect)."],"qa":[["Where do I start?","Contrast, keyboard access, alt text, and form labels — the big four."],["Does accessible mean ugly?","No — constraints breed creativity; the best designs are both."],["How do I test?","Keyboard-only walkthrough, screen reader check, and automated scans — plus disabled users."]]},{"title":"Industrial Design","brief":"Industrial design shapes manufactured products: form, function, materials, and manufacturability in one discipline.","points":["Form follows function — but emotion and brand matter too.","Ergonomics: products must fit human bodies and behaviors.","Design for manufacturing: beautiful concepts must survive tooling and cost.","Sustainability now shapes material and lifecycle choices."],"examples":["A power drill shaped for grip comfort during all-day use.","A chair balancing aesthetics, ergonomics, and flat-pack manufacturing."],"history":["The Bauhaus and Ulm School founded the discipline; Dieter Rams defined its ethics.","Apple's rise made industrial design culturally central."],"uses":["Consumer electronics and appliances.","Furniture and housewares.","Medical and industrial equipment."],"qa":[["What is Dieter Rams' famous principle?","'Less, but better' (Weniger, aber besser) — ten principles of good design."],["Industrial vs product design?","Overlapping; industrial emphasizes physical manufactured goods."],["Do I need engineering skills?","Enough to collaborate — materials and manufacturing literacy is essential."]]},{"title":"Product Design","brief":"Product design (digital) owns the end-to-end creation of apps and services: strategy, UX, UI, and validation.","points":["Discovery: understanding users and business before designing solutions.","Delivery: flows, UI, prototypes, and specs developers build from.","Measurement: defining success metrics and iterating against them.","Product designers bridge business, engineering, and users."],"examples":["A fintech app redesigned around the job of 'paying rent on time'.","A prototype test killing a beloved feature users ignored."],"history":["The title rose with Silicon Valley product teams (2010s).","It merged UX, UI, and product thinking into one role."],"uses":["Tech companies building digital products.","Startups where designers own discovery to delivery.","Complex services needing coherent experience."],"qa":[["Product vs UX designer?","Product design typically includes more strategy, business, and delivery ownership."],["What skills matter most?","Systems thinking, communication, and comfort with ambiguity."],["How do product designers work with PMs?","As partners: PMs own what/why priorities, designers own how it works."]]},{"title":"Packaging Design","brief":"Packaging design protects products, communicates brands, and sells on the shelf — structural and graphic design together.","points":["Structure: materials and engineering that protect through shipping.","Shelf impact: standing out in three seconds among competitors.","Information hierarchy: brand, product, benefits, legal — in reading order.","Unboxing experience extends the brand into the customer's hands."],"examples":["A wine label balancing heritage typography with modern shelf presence.","Sustainable packaging that protects fragile goods with molded fiber."],"history":["Industrial packaging is ancient; branded packaging exploded with mass retail (20th c.).","E-commerce shifted focus to ship-safe and unboxing-friendly."],"uses":["Consumer goods competing on shelves.","E-commerce shipping protection.","Luxury goods where packaging is part of the product."],"qa":[["What matters most on a package?","Findability (brand/product), then desirability, then information."],["Sustainable packaging options?","Reduced materials, recycled content, mono-materials for recyclability."],["How is packaging tested?","Drop, vibration, and compression testing plus shelf and user testing."]]},{"title":"Interior Design","brief":"Interior design shapes indoor spaces: layout, materials, lighting, and furnishings for function and feeling.","points":["Space planning: circulation, zones, and adjacencies before decoration.","Materials and finishes balance aesthetics, durability, and maintenance.","Lighting layers (ambient, task, accent) transform the same space.","Codes and accessibility constrain real projects — design within them."],"examples":["An office planned around collaboration zones and quiet focus areas.","A restaurant interior guiding flow from entry to table to bar."],"history":["Elsie de Wolfe professionalized interior decoration (early 1900s).","Modernism and workplace research shaped contemporary practice."],"uses":["Homes reflecting how people actually live.","Workplaces affecting productivity and wellbeing.","Hospitality and retail driving revenue per square foot."],"qa":[["Interior design vs decorating?","Design includes space planning, codes, and systems; decorating focuses on finishes."],["How do designers charge?","Hourly, flat fee, or percentage of project cost — varies by market."],["What is biophilic design?","Integrating nature (light, plants, materials) for wellbeing."]]},{"title":"Lighting Design","brief":"Lighting design sculpts spaces with light: visibility, mood, focus, and energy in architectural, stage, and product contexts.","points":["Layered lighting: ambient for base, task for work, accent for drama.","Color temperature (warm/cool) sets emotional tone.","Controls (dimming, scenes) adapt spaces through the day.","Energy codes push LED and daylighting strategies."],"examples":["A gallery's track lighting making each artwork glow.","A stage plot shifting mood from warm intimacy to cold tension."],"history":["Edison's bulb (1879) started it; theatrical lighting design became an art in the 20th century.","LEDs (2010s) revolutionized efficiency and control."],"uses":["Architecture and interiors.","Theater, film, and events.","Retail and hospitality atmosphere."],"qa":[["What is color temperature?","Measured in Kelvin: warm (~2700K) to cool (~5000K+) light."],["Why layer lighting?","Single overhead sources flatten; layers create depth and flexibility."],["LED vs traditional?","LED wins on efficiency, lifespan, and control; quality varies — check CRI."]]},{"title":"Furniture Design","brief":"Furniture design creates the objects we live with: balancing ergonomics, materials, craft, and manufacturing.","points":["Ergonomics first: chairs especially must support real bodies for hours.","Material honesty: wood, metal, and upholstery each have languages.","Joinery and construction determine longevity.","Flat-pack and modularity respond to modern living."],"examples":["An ergonomic task chair supporting eight-hour workdays.","A modular sofa reconfiguring for small apartments."],"history":["From Chippendale to the Bauhaus to mid-century modern (Eames, etc.).","IKEA democratized design; makers revived craft."],"uses":["Homes, offices, and hospitality.","Public spaces needing durable beauty.","Collectible design as art."],"qa":[["What makes a chair good?","Support, comfort over time, durability, and honest materials."],["Expensive vs cheap furniture?","Joinery, materials, and ergonomics — cheap copies cut all three."],["Sustainable furniture?","Durable, repairable, and made from responsible materials."]]},{"title":"Fashion Design","brief":"Fashion design creates clothing: silhouette, fabric, construction, and cultural expression.","points":["Silhouette and proportion define a garment's character.","Fabric choice determines drape, durability, and feel.","Pattern-making and construction turn sketches into wearable garments.","Collections balance creative vision with commercial reality."],"examples":["A tailored suit's canvassed construction shaping the shoulder.","A streetwear drop built on graphic identity and scarcity."],"history":["Worth's haute couture (1850s) began modern fashion; ready-to-wear democratized it.","Fast fashion (2000s) sped cycles; sustainability now challenges the model."],"uses":["Apparel from couture to mass market.","Costume for film, theater, and performance.","Cultural expression and identity."],"qa":[["Haute couture vs ready-to-wear?","Couture: handmade to measure; ready-to-wear: factory-made in sizes."],["How do designers start?","Sketching, draping on forms, and deep fabric knowledge."],["Sustainable fashion?","Durable design, responsible materials, and circular models."]]},{"title":"Textile Design","brief":"Textile design creates fabrics: weave, print, color, and texture for fashion, interiors, and industry.","points":["Woven, knitted, and printed structures each behave differently.","Repeat patterns must tile seamlessly.","Colorways adapt one design across palettes.","Performance textiles add function: stretch, waterproofing, fire resistance."],"examples":["A upholstery fabric engineered for 100,000 rubs.","A printed silk scarf with a seamless repeat."],"history":["Textiles are humanity's oldest design medium; industrial looms mechanized it.","Digital printing (2000s) freed designers from screen constraints."],"uses":["Fashion fabrics and interiors.","Technical textiles (medical, automotive, aerospace).","Art textiles and craft."],"qa":[["What is a repeat?","The tileable unit of a pattern — designing seamless repeats is core skill."],["Natural vs synthetic fibers?","Natural: comfort and biodegradability; synthetic: performance and durability."],["How are textiles tested?","Abrasion, colorfastness, shrinkage, and flammability standards."]]},{"title":"Print Design","brief":"Print design creates for ink on paper: books, posters, packaging — where resolution, color, and finishing are physical.","points":["CMYK color and bleed/slug/crop marks prepare files for press.","Paper choice (weight, coating) is a design material.","Typography shines in print: fine details impossible on screen.","Finishing (foil, emboss, die-cut) adds tactile luxury."],"examples":["A wedding invitation with letterpress on cotton paper.","A poster series with spot UV over matte litho."],"history":["Print is the oldest graphic design medium; its craft peaked before digital.","Print's scarcity now makes it premium."],"uses":["Books, magazines, and catalogs.","Stationery and invitations.","Posters and art prints."],"qa":[["What is bleed?","Artwork extending past the trim edge so cuts show no white sliver."],["300 DPI — why?","The resolution where print looks sharp at reading distance."],["Is print dead?","No — diminished but premium; print now signals care."]]},{"title":"Editorial Design","brief":"Editorial design shapes publications: magazines, books, and reports where long-form content meets visual rhythm.","points":["Grids and templates create consistency across hundreds of pages.","Typographic systems handle headlines, body, captions, and pull quotes.","Pacing: varying layouts keeps long documents engaging.","Cover design sells the content inside."],"examples":["A magazine feature spreading photography across a gatefold.","An annual report making financials readable through infographics."],"history":["Magazines (19th c.) and modernist art directors (Brodovitch) defined the craft.","Digital publishing added interactive longform."],"uses":["Magazines and books.","Reports and white papers.","Digital longform and newsletters."],"qa":[["What makes a good magazine layout?","Rhythm: alternating dense and airy spreads, strong entry points."],["Print or digital editorial?","Both — the principles transfer, the constraints differ."],["How do you design a 200-page report?","Systems first: templates, styles, and grids before page one."]]},{"title":"Motion Design","brief":"Motion design brings graphics to life: animation for interfaces, film, and brand storytelling.","points":["Timing and easing make motion feel natural — the 12 principles of animation apply.","Purposeful motion guides attention and explains change; decoration distracts.","Brand motion systems define consistent movement languages.","Performance: 60fps and reduced-motion respect for accessibility."],"examples":["An app onboarding sequence animating through key features.","A logo sting opening every brand video."],"history":["Title sequences (Saul Bass, 1950s) birthed motion graphics.","After Effects (1993) and the web made motion ubiquitous."],"uses":["Film titles and broadcast graphics.","UI animation and micro-interactions.","Explainers and advertising."],"qa":[["How long should UI animation be?","Typically 200-400ms — felt, not watched."],["What is easing?","Acceleration curves making motion feel physical rather than robotic."],["Do I need to code?","Tools handle most; code (Lottie, CSS) helps for product motion."]]},{"title":"Illustration","brief":"Illustration creates original imagery: editorial, commercial, and narrative art with a human hand.","points":["Style is a strategic choice matching audience and message.","Conceptual thinking: the best illustrations carry ideas, not just decoration.","Technique spans traditional media to vector to 3D.","Consistency across a series matters more than any single image."],"examples":["Editorial illustrations distilling a complex article into one image.","A children's book series with a cohesive visual world."],"history":["Illustration predates design; the golden age of illustration (late 19th-early 20th c.) set standards.","Digital tools expanded styles while print decline shifted markets."],"uses":["Publishing and editorial.","Advertising and packaging.","Storyboarding and concept art."],"qa":[["Illustration vs graphic design?","Illustrators create imagery; designers compose communications — often collaborating."],["Will AI replace illustrators?","AI generates images; art direction, taste, and original voice remain human."],["How do illustrators find work?","Portfolios, agents, and relationships with art directors."]]},{"title":"Data Visualization Design","brief":"Data visualization turns numbers into understanding: choosing the right chart and designing it honestly.","points":["Choose encodings by task: bars for comparison, lines for trend, scatter for correlation.","Honesty: no truncated axes or cherry-picked ranges that mislead.","Reduce clutter: every element should earn its ink (data-ink ratio).","Interactivity (filtering, tooltips) serves exploration; static serves explanation."],"examples":["A line chart revealing a trend invisible in a table of 10,000 rows.","A dashboard where executives grasp KPIs in seconds."],"history":["Playfair's charts (1780s) invented statistical graphics; Tufte (1980s) theorized them.","D3.js (2011) made custom interactive visualization mainstream."],"uses":["Business dashboards and reporting.","Journalism explaining complex stories.","Scientific communication."],"qa":[["What is the most misused chart?","The pie chart — humans judge angles poorly; bars usually win."],["How do I avoid misleading?","Start axes at zero for bars, show full context, label honestly."],["Static or interactive?","Static for presenting conclusions; interactive for exploring data."]]},{"title":"Wayfinding and Environmental Graphics","brief":"Wayfinding design guides people through spaces: signage systems that orient, direct, and reassure.","points":["Progressive disclosure: overview maps, then directional signs, then identification.","Legibility at distance determines type size, contrast, and placement.","Consistent visual language across a whole campus or transit system.","Test with real users navigating — confusion points reveal failures."],"examples":["An airport signage system guiding millions who speak different languages.","A hospital wayfinding system reducing missed appointments."],"history":["Modernist signage (1960s-70s) systematized public information design.","Digital displays added real-time wayfinding."],"uses":["Airports, hospitals, campuses.","Transit systems and cities.","Large venues and events."],"qa":[["What makes signage fail?","Too much information, poor placement, or jargon instead of plain language."],["Digital or static signs?","Static for permanent guidance; digital for changing information."],["How do you design for multiple languages?","Pictograms, consistent placement, and prioritized translations."]]},{"title":"Exhibition Design","brief":"Exhibition design creates museum, trade show, and retail experiences: space, narrative, and interaction.","points":["Narrative flow: exhibitions tell stories through sequence and pacing.","Lighting and materials shape atmosphere and focus.","Interactive elements engage without overwhelming the content.","Accessibility: exhibitions must welcome all bodies and senses."],"examples":["A museum exhibition guiding visitors through a chronological story.","A trade-show booth drawing crowds with interactive demos."],"history":["World's fairs (19th c.) pioneered spectacular exhibition design.","Experience design (2000s) made interactivity central."],"uses":["Museums and galleries.","Trade shows and brand experiences.","Retail environments."],"qa":[["How do you keep visitors engaged?","Varied pacing: mix media, scale, and interaction types."],["What is interpretive design?","Designing how content is explained — labels, media, guides."],["Budget vs impact?","Strong narrative beats expensive tech; clarity is the luxury."]]},{"title":"Service Design","brief":"Service design orchestrates entire services across touchpoints: the frontstage users see and the backstage that delivers it.","points":["Journey maps reveal the end-to-end experience, including pain points.","Blueprints connect frontstage interactions to backstage processes.","Touchpoints (digital, physical, human) must feel like one service.","Co-design involves users and staff in creating the service."],"examples":["Redesigning a hospital discharge so patients actually understand next steps.","A bank unifying branch, app, and call-center experiences."],"history":["The term emerged in the 1990s-2000s (Bill Hollins, Live|Work).","Governments adopted service design for public services (UK GDS)."],"uses":["Healthcare, banking, and government services.","Hospitality and transportation.","Any multi-touchpoint customer experience."],"qa":[["Service vs UX design?","UX often focuses on digital touchpoints; service design covers the whole journey."],["What is a service blueprint?","A map linking customer actions to frontstage and backstage processes."],["How do you measure service design?","Journey metrics: completion, satisfaction, and effort across touchpoints."]]},{"title":"Design Thinking","brief":"Design thinking is a human-centered innovation process: empathize, define, ideate, prototype, test.","points":["Empathize: understand users deeply before solving.","Define: frame the right problem — solutions to wrong problems fail.","Ideate broadly, then converge; quantity enables quality.","Prototype and test cheaply and early, iterating toward fit."],"examples":["A team reframing 'design a better waiting room' as 'reduce perceived wait time'.","Paper prototypes testing three directions in one week."],"history":["Stanford d.school and IDEO popularized it (2000s).","Roots in design methodology research (1960s-80s)."],"uses":["Innovation in companies of all sizes.","Social challenges and public services.","Teaching creative problem-solving."],"qa":[["Is design thinking just brainstorming?","No — it's a disciplined cycle from empathy through tested prototypes."],["Does it work for everything?","Best for ambiguous, human problems; less for purely technical optimization."],["Criticisms?","That it's oversimplified and workshop-ified — depth matters more than sticky notes."]]},{"title":"Design Research Methods","brief":"Design research methods generate the insights design needs: from ethnography to analytics to experiments.","points":["Generative research discovers opportunities; evaluative research tests solutions.","Diary studies capture behavior over time in context.","Surveys quantify; interviews explain.","Triangulation: multiple methods converging beats any single study."],"examples":["A diary study revealing how people actually manage medications.","A survey quantifying which of five concepts resonates."],"history":["Methods come from anthropology, psychology, and market research.","Digital products added analytics and A/B testing at scale."],"uses":["Informing strategy with evidence.","De-risking big design bets.","Building organizational empathy."],"qa":[["Qualitative or quantitative?","Both — qualitative for why, quantitative for how much."],["How do I choose a method?","Match the method to the question and the decision it informs."],["What is triangulation?","Using multiple methods so weaknesses of one are covered by others."]]},{"title":"Design Critique","brief":"Design critique is structured feedback: evaluating work against goals to improve it, not to judge the designer.","points":["Critique the work against objectives, not personal taste.","Ask questions before giving opinions — understanding precedes judgment.","Be specific and actionable: 'the hierarchy buries the CTA' beats 'I don't like it'.","Separate critique (exploration) from approval (decision)."],"examples":["A weekly crit where designers present work-in-progress for peer feedback.","A critique reframing a 'ugly' complaint into a hierarchy problem."],"history":["Critique comes from art and architecture studio tradition.","Design teams formalized it as product design scaled."],"uses":["Improving work through diverse perspectives.","Building shared standards and vocabulary.","Onboarding designers into team culture."],"qa":[["How do I give good critique?","Reference goals, be specific, suggest directions — and ask questions first."],["How do I receive critique?","Listen, ask clarifying questions, decide later — don't defend in the moment."],["Critique vs review?","Critique explores and improves; review decides and approves."]]},{"title":"Universal Design","brief":"Universal design creates products and environments usable by all people, regardless of age or ability — from the start.","points":["The seven principles: equitable, flexible, simple, perceptible, error-tolerant, low-effort, appropriately sized.","Design for the edges: solutions for extreme users usually help everyone.","Curb-cut effect: accessibility features benefit the mainstream.","Involves disabled users as co-designers, not afterthoughts."],"examples":["Curb cuts helping wheelchairs, strollers, and delivery carts alike.","Voice control designed for accessibility becoming mainstream convenience."],"history":["Ron Mace coined 'universal design' (1980s-90s).","Disability rights movements drove adoption into law and practice."],"uses":["Architecture and public space.","Products from kitchen tools to software.","Policy and standards."],"qa":[["Universal vs accessible design?","Universal aims to include everyone from the start; accessible often adapts for specific needs."],["Is it more expensive?","Cheaper than retrofitting — and it expands markets."],["Examples in tech?","Captions, voice assistants, and dark mode all have universal-design roots."]]},{"title":"Sustainable Design","brief":"Sustainable design minimizes environmental harm across a product's life: materials, energy, longevity, and end of life.","points":["Life-cycle thinking: impacts from extraction through disposal, not just use.","Design for durability and repair beats design for replacement.","Material choice: renewable, recycled, and non-toxic where possible.","Systems matter: the most sustainable product in a wasteful system still wastes."],"examples":["A phone designed for battery and screen replacement extending life to seven years.","Packaging redesigned to eliminate plastic while protecting goods."],"history":["Victor Papanek's 'Design for the Real World' (1971) sounded the alarm.","Circular economy frameworks (2010s) gave business models to the ethics."],"uses":["Products, packaging, and buildings.","Corporate sustainability commitments.","Policy and eco-labeling."],"qa":[["What is circular design?","Designing products and systems where materials cycle endlessly, not to landfill."],["Is sustainable design more expensive?","Sometimes upfront; lifecycle costs often favor durability."],["Greenwashing?","False sustainability claims — real sustainable design is verifiable."]]},{"title":"Design Ethics","brief":"Design ethics asks what designers owe users and society: honesty, inclusion, and responsibility for consequences.","points":["Dark patterns manipulate users — ethical design respects autonomy.","Inclusive design considers who is excluded and why.","Designers share responsibility for what their work enables.","Codes of ethics guide, but judgment decides."],"examples":["Refusing a project that would deceive vulnerable users.","Designing consent flows people actually understand."],"history":["Papanek and later critics challenged design's complicity in harm.","Tech's scale (2010s) made design ethics urgent and public."],"uses":["Building trustworthy products.","Protecting vulnerable users.","Professional integrity and reputation."],"qa":[["What are dark patterns?","Interfaces tricking users: hidden costs, forced continuity, confirmshaming."],["Can designers refuse work?","Yes — and the best ones do when values conflict."],["Ethics vs business?","Short-term tension, long-term alignment: trust is business value."]]},{"title":"Design History: Bauhaus","brief":"The Bauhaus (1919-1933) fused art, craft, and technology, shaping modern design's language of simplicity and function.","points":["'Form follows function' became the modernist creed.","Workshops united artists and craftspeople across media.","Typography and geometric abstraction defined the visual language.","Its closure by the Nazis scattered masters who spread the ideas worldwide."],"examples":["The Barcelona chair embodying modernist furniture ideals.","Bauhaus typography influencing a century of graphic design."],"history":["Founded by Walter Gropius in Weimar (1919); closed under Nazi pressure (1933).","Masters included Kandinsky, Klee, Moholy-Nagy, and Albers."],"uses":["Understanding why modern design looks the way it does.","Design education's foundation worldwide.","A reference point for every 'less is more' debate."],"qa":[["What did the Bauhaus actually make?","Buildings, furniture, textiles, typography — total design environments."],["Why does it still matter?","Its principles underpin modernism in every design discipline."],["Criticisms?","That its universalism ignored culture and its functionalism could feel cold."]]},{"title":"Swiss Typography Style","brief":"The International Typographic Style — Swiss Style — brought grid-based, objective clarity to graphic design in the 1950s-60s.","points":["Grids impose mathematical order on layouts.","Sans-serif type (Helvetica, Univers) set flush left, ragged right.","Objective photography over illustration; asymmetry over symmetry.","Clarity as an ethical stance: design should communicate, not decorate."],"examples":["A concert poster using only Helvetica, a grid, and one red accent.","Corporate identity systems built on Swiss principles."],"history":["Emerged in Zurich and Basel (1950s); Müller-Brockmann's grid systems codified it.","It became the global corporate style of the 1960s-70s."],"uses":["Corporate identity and information design.","Editorial systems needing clarity.","The foundation of much UI design."],"qa":[["Why Helvetica?","Its neutrality embodied Swiss objectivity — though its ubiquity later bred backlash."],["Is Swiss Style boring?","Critics say so; practitioners say clarity is never boring."],["Does it still influence design?","Enormously — flat UI design is its digital heir."]]},{"title":"Minimalism in Design","brief":"Minimalism strips design to essentials: fewer elements, more meaning per element.","points":["'Less, but better' — remove until breaking, then add back what's needed.","Whitespace is a material, not emptiness.","Restraint demands excellence: every remaining element must be perfect.","Minimalism is a means (clarity) not an end (emptiness)."],"examples":["A product page with one image, essential copy, and a single action.","A logo reduced to its most essential geometry."],"history":["Roots in Japanese aesthetics, Bauhaus, and 1960s art.","Apple and Muji made it a commercial language."],"uses":["Luxury branding signaling confidence.","Interfaces reducing cognitive load.","Architecture and interiors."],"qa":[["Minimalism vs simplicity?","Minimalism is an aesthetic; simplicity is usability — related but distinct."],["Can minimalism go too far?","Yes — hiding necessary complexity creates confusion, not clarity."],["Is minimalism still trendy?","It cycles; the principle of restraint is timeless."]]},{"title":"Material Design Language","brief":"Google's Material Design is a comprehensive design language: tactile surfaces, bold color, and meaningful motion.","points":["Material metaphor: interfaces as layered paper with depth and shadows.","Bold color and typography create hierarchy and brand.","Motion explains spatial relationships between screens.","Components and tokens make it implementable at scale."],"examples":["An Android app feeling native through Material components.","A web dashboard using Material's elevation and motion consistently."],"history":["Launched 2014; Material You (2021) added dynamic personalization.","It standardized Android's fragmented visual landscape."],"uses":["Android app design.","Cross-platform products wanting a complete system.","Learning component-based design."],"qa":[["Must I follow Material exactly?","No — adapt it; the principles matter more than the components."],["Material vs iOS guidelines?","Different philosophies; follow each platform's conventions for native feel."],["Is Material still relevant?","Yes — it evolves (Material You) and remains the Android standard."]]},{"title":"Design Tools","brief":"Design tools are the instruments of the craft: from Figma to Blender, each shapes what's possible.","points":["Vector tools (Figma, Illustrator) for interfaces and graphics.","3D and motion tools (Blender, After Effects) for depth and movement.","Prototyping is now built into design tools, collapsing workflows.","Tool fluency matters less than design judgment — tools change, principles don't."],"examples":["A team collaborating in real time on a Figma file.","A 3D mockup presenting packaging before production."],"history":["From paste-up to Photoshop (1990) to Sketch to Figma's collaboration (2016).","AI-assisted tools (2020s) now generate variations and assets."],"uses":["Professional design production.","Collaboration between designers and developers.","Rapid iteration and handoff."],"qa":[["Which tool should I learn?","Figma for product/UI; Illustrator for vector craft; learn principles first."],["Will AI replace design tools?","It's becoming part of them — generating options designers direct."],["Free vs paid tools?","Free tools (Figma, Blender, Penpot) now rival paid for most work."]]},{"title":"Design Handoff","brief":"Design handoff transfers designs to developers accurately: specs, assets, and communication that survive translation.","points":["Specs document spacing, type, color, and behavior — tools auto-generate much of it.","Assets exported at right formats and resolutions (SVG, 2x/3x).","Design systems reduce handoff to composition, not reinvention.","Conversation beats documentation: designers and developers collaborate, not throw over walls."],"examples":["A developer building pixel-perfect from inspectable Figma specs.","A handoff checklist catching missing empty states before build."],"history":["Redlines and spec docs (2000s) gave way to inspectable files (2010s).","Design systems and tokens further collapsed the gap."],"uses":["Shipping designs as intended.","Reducing rework and friction.","Scaling design across engineering teams."],"qa":[["What causes handoff failures?","Missing states, unbuildable designs, and no designer availability during build."],["Should designers code?","Enough to understand constraints — fluency beats full-stack expectations."],["What is design QA?","Designers reviewing built work against specs before release."]]},{"title":"Portfolio Design","brief":"A design portfolio proves capability: curated case studies showing process, thinking, and outcomes.","points":["Case studies over galleries: problem, process, decisions, outcomes.","Curate ruthlessly — ten strong projects beat thirty mixed ones.","Show process: sketches, research, iterations, not just finals.","Tailor to the audience: the portfolio is itself a design project."],"examples":["A case study tracing a checkout redesign from research to +15% conversion.","A portfolio site whose own design demonstrates the designer's skill."],"history":["Portfolios are ancient in art; digital portfolios (2000s) made them universal.","Case-study format became the hiring standard in product design."],"uses":["Getting hired or winning clients.","Freelance credibility.","Career reflection and growth."],"qa":[["How many projects?","Five to ten strong ones, tailored per application."],["What if my work is under NDA?","Show process with redacted details, or create self-initiated projects."],["Website or PDF?","Website for breadth; PDF for tailored applications."]]},{"title":"Future of Design (AI-Assisted)","brief":"AI-assisted design is reshaping the craft: generative tools produce options while designers direct, curate, and take responsibility.","points":["Generative tools produce variations, layouts, and imagery from prompts.","Designers shift toward direction, curation, and systems thinking.","Taste and judgment become more valuable, not less.","Ethics: attribution, bias, and the value of human craft."],"examples":["A designer generating 50 layout directions, then refining the best three.","AI-assisted user research synthesis across hundreds of interviews."],"history":["Generative design is old (1960s); AI made it mainstream in the 2020s.","The craft is renegotiating what 'designer' means."],"uses":["Accelerating exploration and production.","Personalization at unprecedented scale.","New mediums and interactions."],"qa":[["Will AI replace designers?","It replaces tasks, not judgment — designers who direct AI outpace those who don't."],["What skills matter now?","Taste, systems thinking, ethics, and the ability to direct AI well."],["Should I learn prompt craft?","Yes — it's becoming as basic as learning design software was."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-design-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('design',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();